// Read-only inspection: list workspace page contents + key component internals
const run = async () => {
  const out = {};

  // Workspace page
  const wp = figma.root.children.find(p => p.id === '3:2');
  out.workspace = { name: wp.name, id: wp.id, children: wp.children.map(c => ({ id: c.id, name: c.name, type: c.type })) };

  // Inspect components page symbols: Button 1:23, Text Field 1:26, Status Bar 1:33, Home Indicator 1:43
  const compsPage = figma.root.children.find(p => p.id === '1:3');
  const inspect = (id) => {
    const n = compsPage.findOne(n => n.id === id);
    if (!n) return { error: 'not found ' + id };
    const desc = { id: n.id, name: n.name, type: n.type, x: n.x, y: n.y, w: n.width, h: n.height };
    if ('fills' in n && n.fills) desc.fills = Array.isArray(n.fills) ? n.fills.map(f => ({ type: f.type, color: f.color, opacity: f.opacity, visible: f.visible })) : n.fills;
    if ('strokes' in n && n.strokes) desc.strokes = n.strokes.map(s => ({ type: s.type, color: s.color }));
    if (n.type === 'TEXT') { desc.characters = n.characters; desc.fontName = n.fontName; desc.fontSize = n.fontSize; desc.textCase = n.textCase; desc.lineHeight = n.lineHeight; desc.letterSpacing = n.letterSpacing; desc.textAlignHorizontal = n.textAlignHorizontal; }
    if ('cornerRadius' in n) desc.cornerRadius = n.cornerRadius;
    if ('effects' in n) desc.effects = n.effects.map(e => ({ type: e.type, radius: e.radius, visible: e.visible }));
    desc.children = n.children ? n.children.map(c => ({ id: c.id, name: c.name, type: c.type })) : undefined;
    return desc;
  };
  out.button = inspect('1:23');
  out.textField = inspect('1:26');
  out.statusBar = inspect('1:33');
  out.homeIndicator = inspect('1:43');
  out.shellFrame = inspect('1:32');

  // Media: image fills inside photo symbols - check a couple
  const mediaPage = figma.root.children.find(p => p.id === '1:4');
  const checkFills = (symId) => {
    const s = mediaPage.findOne(n => n.id === symId);
    if (!s) return null;
    const collect = [];
    const walk = (n) => {
      if (n.type === 'RECTANGLE' || n.type === 'ELLIPSE' || n.type === 'FRAME') {
        if (n.fills && Array.isArray(n.fills)) {
          for (const f of n.fills) {
            if (f.type === 'IMAGE') {
              const img = (typeof figma.getImageByHash === 'function') ? null : null;
              collect.push({ id: n.id, w: n.width, h: n.height, imageHash: f.imageHash, scaleMode: f.scaleMode });
            }
          }
        }
      }
      if (n.children) n.children.forEach(walk);
    };
    walk(s);
    return collect;
  };
  out.photoBromo = checkFills('1:351');
  out.mapImage = checkFills('1:346');
  out.avatarKari = checkFills('1:293');
  out.logoApple = checkFills('1:347');
  out.iconHeart = checkFills('1:308');

  // list all media symbols with ids
  out.mediaSymbols = mediaPage.findAll(n => n.type === 'COMPONENT').map(c => ({ id: c.id, name: c.name, w: c.width, h: c.height }));

  figma.ui.postMessage({ type: 'inspect-done', out });
  return JSON.stringify(out);
};
