const results = [];
function rgb(c){ if(!c) return null; return {r:+c.r.toFixed(3), g:+c.g.toFixed(3), b:+c.b.toFixed(3)}; }
function fmtFills(n){
  try{
    if(!n.fills || !n.fills.length) return null;
    return n.fills.map(f=>{
      const o={type:f.type, visible:f.visible!==false};
      if(f.type==='SOLID'){ o.color=rgb(f.color); if(f.opacity!==undefined) o.opacity=+f.opacity.toFixed(2); }
      if(f.type==='IMAGE'){ o.imageHash=f.imageHash? f.imageHash.slice(0,8): null; o.scaleMode=f.scaleMode; }
      if(f.type==='GRADIENT_LINEAR'||f.type==='GRADIENT_RADIAl'||f.type==='GRADIENT_ANGULAR'){ o.gradientStops=(f.gradientStops||[]).map(s=>({pos:+s.position.toFixed(2), color:rgb(s.color)})); o.color=null; }
      return o;
    });
  }catch(e){ return 'ERR'; }
}
function textInfo(n){
  if(n.type!=='TEXT') return null;
  try{
    const fs = typeof n.fontSize==='function' ? n.fontSize : null;
    return {characters:n.characters.slice(0,40), fontSize: n.fontSize, fontName:n.fontName, fg: rgb(n.fills&&n.fills[0]?n.fills[0].color:null), lineHeight:n.lineHeight?{unit:n.lineHeight.unit, value:n.lineHeight.value}:null};
  }catch(e){ return 'ERR:'+e.message; }
}
function walk(n, depth, maxDepth){
  if(depth>maxDepth) return;
  const rec = {id:n.id, name:n.name, type:n.type};
  if(n.type==='COMPONENT'||n.type==='COMPONENT_SET') rec.isComp=true;
  rec.fills = fmtFills(n);
  if(n.type==='TEXT') rec.text=textInfo(n);
  if('cornerRadius' in n && n.cornerRadius!==undefined){ try{rec.cornerRadius=n.cornerRadius}catch(e){} }
  if('strokeWeight' in n && n.strokeWeight!==undefined && n.strokes && n.strokes.length){ try{rec.stroke={w:n.strokeWeight, c:rgb(n.strokes[0].color)}}catch(e){} }
  if(n.type==='RECTANGLE'||n.type==='ELLIPSE'||n.type==='FRAME'||n.type==='INSTANCE'){ rec.size={w:+(n.width||0).toFixed(1), h:+(n.height||0).toFixed(1)}; }
  results.push(rec);
  if(n.children){ for(const c of n.children) walk(c, depth+1, maxDepth); }
}
for(const id of rootIds){
