// safe instance maker: component.createInstance() else clone
function mkInst(id){
  const n = figma.getNodeById(id);
  if(!n) return null;
  const t = n.type;
  if(t==='COMPONENT' || t==='COMPONENT_SET'){
    try { const i=n.createInstance(); if(i) return i; } catch(e){}
    try { return figma.createInstance(n); } catch(e2){}
  }
  try { return n.clone(); } catch(e3){ return null; }
}
function iconInst(id, x, y, size, color){
  const inst = mkInst(id); if(!inst) return null;
  inst.x=x; inst.y=y;
  if(size){ const k=size/(inst.width||size); inst.resize(inst.width*k, inst.height*k); }
  if(color){ (function walk(nn){ for(const ch of nn.children){ if(ch.fills && ch.fills.length && ch.fills[0].type==='SOLID'){ ch.fills=[{type:'SOLID',color:hex(color)}]; } if(ch.children) walk(ch); } })(inst); }
  return inst;
}
function iconFromParts(parts, x, y, size){
  // parts: array of source ids to merge into one
  const first = mkInst(parts[0]); if(!first) return null;
  first.x=x; first.y=y;
  if(size){ const k=size/(first.width||size); first.resize(first.width*k, first.height*k); }
  return first;
}

