  try{ if(n.characters!==undefined) extra=' chars="'+n.characters+'"'; }catch(e){}
  try{ if(n.fills && n.fills[0] && n.fills[0].type==='SOLID'){ const c=n.fills[0].color; extra+=' fill=#'+[c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join(''); } }catch(e){}
  try{ if(n.fontName) extra+=' font='+n.fontName.family+'/'+n.fontName.style+' '+n.fontSize; }catch(e){}
  console.log(pad+n.type+' '+n.name+' id='+n.id+extra);
  if(n.children){ for(const c of n.children) dumpTree(c, depth+1); }
