const hex = (h) => { const s=h.replace('#',''); return { r:parseInt(s.slice(0,2),16)/255, g:parseInt(s.slice(2,4),16)/255, b:parseInt(s.slice(4,6),16)/255 }; };
const BRAND='#684DEC', INK='#23243A', SEC='#6F7080', TER='#9B98AD', BORDER='#ECEBF3', SURF='#F7F6FB', WHITE='#FFFFFF', AMBER='#FFB800';
function R(x,y,w,h,fill,corners,stroke){ const r=figma.createRectangle(); r.x=x; r.y=y; r.resize(w,h); r.fills= fill==null? [] : [{type:'SOLID', color:hex(fill)}]; if(corners!=null){ r.cornerRadius=corners; } if(stroke){ r.strokes=[{type:'SOLID',color:hex(stroke)}]; r.strokeWeight=1; } return r; }
function F(x,y,w,h,fill){ const f=figma.createFrame(); f.x=x; f.y=y; f.resize(w,h); f.name='F'; f.fills= fill==null? [] : [ {type:'SOLID', color:hex(fill)} ]; f.clipsContent=false; return f; }
async function T(str, x, y, size, weight, color, w, align){
  const t=figma.createText(); t.characters=str; t.fontSize=size; t.fontName={family:'Inter', style:weight}; t.fills=[{type:'SOLID', color:hex(color)}]; t.x=x; t.y=y;
  if(w&&w>0){ t.resize(w, t.height); }
  if(align) t.textAlignHorizontal=align;
  return t;
}
function mkInst(id){
  const n = figma.getNodeById(id); if(!n) return null;
  try{ if(n.type==='COMPONENT'||n.type==='COMPONENT_SET'){ const i=n.createInstance(); if(i) return i; } }catch(e){}
  try{ return figma.createInstance(n); }catch(e2){ }
  try{ return n.clone(); }catch(e3){ return null; }
}
function iconInst(id, x, y, size, color){
  const inst = mkInst(id); if(!inst) return null;
  inst.x=x; inst.y=y;
  if(size){ const k=size/(inst.width||size); inst.resize(inst.width*k, inst.height*k); }
  if(color){ (function walk(nn){ for(const ch of nn.children){ if(ch.fills && ch.fills.length && ch.fills[0].type==='SOLID'){ ch.fills=[{type:'SOLID',color:hex(color)}]; } if(ch.children) walk(ch); } })(inst); }
  return inst;
}
function photoClip(parent, srcId, x, y, w, h, radius){
  const clip=figma.createFrame(); clip.x=x; clip.y=y; clip.resize(w,h); clip.clipsContent=true; clip.fills=[]; clip.name='photo';
  if(radius!=null) clip.cornerRadius=radius;
  const inst=mkInst(srcId);
  if(inst){ const scale=Math.max(w/(inst.width||w), h/(inst.height||h)); const nw=(inst.width||w)*scale, nh=(inst.height||h)*scale; inst.resize(nw,nh); inst.x=(w-nw)/2; inst.y=(h-nh)/2; clip.appendChild(inst); }
  parent.appendChild(clip); return clip;
}

