function dump(n, depth){
  const pad = '  '.repeat(depth);
  const parts = [pad + n.type.slice(0,4).toUpperCase() + ' ' + n.name];
  if (n.type==='TEXT') parts.push('"' + n.characters.slice(0,34) + '"' + ' sz=' + n.fontSize + ' ' + (n.fontName?n.fontName.family+'/'+n.fontName.style:''));
