    parts.push('f='+fs);
  }
  if (n.cornerRadius!==undefined && n.cornerRadius>0) parts.push('r='+n.cornerRadius);
  if (n.strokes!==undefined && n.strokes.length) parts.push('st='+n.strokes.map(s=>s.type).join());
  let line = parts.join(' | ');
  if (line.length>110) line = line.slice(0,110)+'…';
  const out = [line];
  if (n.children) n.children.forEach(c => out.push(dump(c, depth+1)));
  return out.join('\n');
}
