function FR(name,x,y,w,h,fill,clip=true){
  const f=figma.createFrame(); f.name=name; f.resize(w,h); f.x=x; f.y=y;
  f.fills= fill?[{type:'SOLID',color:HX(fill)}]:[];
  f.clipsContent=clip; page.appendChild(f); return f;
}
function RC(p,x,y,w,h,fill,r){
  const n=figma.createRectangle(); n.x=x;n.y=y;n.resize(w,h);
  n.fills= fill?[{type:'SOLID',color:HX(fill)}]:[];
  if(r)n.cornerRadius=r; p.appendChild(n); return n;
}
function TXT(p,x,y,str,size,weight,color,w,align,lh){
  const t=figma.createText();
  t.fontName={family:'Inter',style:weight}; t.fontSize=size; t.characters=str;
  t.fills=[{type:'SOLID',color:HX(color)}]; t.x=x; t.y=y;
  if(w){ t.resize(w,size); t.textAutoResize='HEIGHT'; t.textAlignHorizontal=align||'LEFT'; } else { t.textAutoResize='WIDTH_AND_HEIGHT'; if(align) t.textAlignHorizontal=align; }
  if(lh) t.lineHeight={value:lh,unit:'PIXELS'};
  p.appendChild(t); return t;
}
function INST(id,x,y,w,h,name,parent){
  const c=figma.getNodeById(id); const inst=c.createInstance();
  inst.x=x; inst.y=y; if(w&&h) inst.resize(w,h); if(name) inst.name=name;
  (parent||page).appendChild(inst); return inst;
}
function SETTXT(inst,str){
  const t=inst.findOne(n=>n.type==='TEXT'); if(t) t.characters=str; return inst;
}
